"use client";

import { useState } from "react";
import Link from "next/link";
import {
  ArrowUpRight,
  BarChart3,
  Briefcase,
  Building2,
  BusFront,
  Camera,
  ChevronLeft,
  ChevronRight,
  Fish,
  GraduationCap,
  HandHeart,
  HeartPulse,
  Landmark,
  Leaf,
  MapPinned,
  RadioTower,
  Sprout,
  Trophy,
  TriangleAlert,
  Users,
} from "lucide-react";
import { SectionHeading } from "@/components/portal/section-heading";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { formatCompactNumber } from "@/lib/utils/formatters";

const topicIcons = {
  ekonomi: BarChart3,
  kependudukan: Users,
  kesehatan: HeartPulse,
  pendidikan: GraduationCap,
  infrastruktur: Building2,
  pemerintahan: Landmark,
  sosial: HandHeart,
  lingkungan: Leaf,
  ketenagakerjaan: Briefcase,
  pertanian: Sprout,
  perikanan: Fish,
  transportasi: BusFront,
  pariwisata: Camera,
  kebencanaan: TriangleAlert,
  kominfo: RadioTower,
  olahraga: Trophy,
  pertanahan: MapPinned,
} as const;

export type TopicCarouselIconKey = keyof typeof topicIcons;

export interface TopicCarouselItem {
  label: string;
  datasetCount: number;
  href: string;
  iconKey: TopicCarouselIconKey;
  accentColor: string;
}

export interface TopicCarouselSlide {
  id: string;
  label: string;
  description: string;
  items: TopicCarouselItem[];
}

interface TopicCarouselProps {
  title: string;
  description: string;
  slides: TopicCarouselSlide[];
}

export function TopicCarousel({ title, description, slides }: TopicCarouselProps) {
  const [activeIndex, setActiveIndex] = useState(0);

  if (!slides.length) {
    return null;
  }

  const activeSlide = slides[activeIndex];

  const goToSlide = (targetIndex: number) => {
    setActiveIndex((targetIndex + slides.length) % slides.length);
  };

  return (
    <section aria-label="Topik data prioritas">
      <Card className="overflow-hidden border-[var(--color-border)] bg-gradient-to-br from-[#f8f7f3] via-white to-[#edf2fb] p-5 sm:p-6">
        <div className="flex flex-col gap-5 border-b border-[rgba(191,199,214,0.75)] pb-5 lg:flex-row lg:items-end lg:justify-between">
          <div className="space-y-3">
            <span className="inline-flex w-fit rounded-full border border-[#ead7d1] bg-white/90 px-3 py-1.5 text-[11px] font-bold uppercase tracking-[0.24em] text-[var(--color-primary)] shadow-sm">
              Topik Data
            </span>
            <SectionHeading
              title={title}
              description={description}
              titleClassName="text-2xl sm:text-3xl"
              descriptionClassName="text-sm sm:text-base"
            />
          </div>

          <div className="flex items-center gap-2 self-start lg:self-auto">
            <span className="rounded-full border border-[var(--color-border)] bg-white px-3 py-2 text-xs font-semibold uppercase tracking-[0.18em] text-[var(--color-muted)]">
              Slide {activeIndex + 1}/{slides.length}
            </span>
            <Button
              type="button"
              variant="secondary"
              size="icon"
              onClick={() => goToSlide(activeIndex - 1)}
              aria-label="Lihat slide topik sebelumnya"
              className="rounded-full"
            >
              <ChevronLeft className="size-5" />
            </Button>
            <Button
              type="button"
              variant="secondary"
              size="icon"
              onClick={() => goToSlide(activeIndex + 1)}
              aria-label="Lihat slide topik berikutnya"
              className="rounded-full"
            >
              <ChevronRight className="size-5" />
            </Button>
          </div>
        </div>

        <div className="mt-5 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
          <div aria-live="polite">
            <p className="m-0 text-xs font-bold uppercase tracking-[0.18em] text-[var(--color-primary)]">
              {activeSlide.label}
            </p>
            <p className="mb-0 mt-2 max-w-3xl text-sm leading-relaxed text-[var(--color-muted)] sm:text-base">
              {activeSlide.description}
            </p>
          </div>

          <div className="hidden items-center gap-2 sm:flex">
            {slides.map((slide, index) => (
              <button
                key={slide.id}
                type="button"
                onClick={() => goToSlide(index)}
                aria-label={`Tampilkan ${slide.label}`}
                aria-pressed={activeIndex === index}
                className={`h-2.5 rounded-full transition-all ${
                  activeIndex === index ? "w-10 bg-[var(--color-primary)]" : "w-2.5 bg-[#c6cfdb]"
                }`}
              />
            ))}
          </div>
        </div>

        <div className="mt-5 overflow-hidden">
          <div
            className="flex transition-transform duration-500 ease-out"
            style={{ transform: `translateX(-${activeIndex * 100}%)` }}
          >
            {slides.map((slide, slideIndex) => (
              <div key={slide.id} className="min-w-full" aria-hidden={slideIndex !== activeIndex}>
                <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
                  {slide.items.map((item) => {
                    const Icon = topicIcons[item.iconKey];

                    return (
                      <Link key={item.label} href={item.href} className="group h-full">
                        <article className="relative flex h-full flex-col gap-5 rounded-[26px] border border-[rgba(191,199,214,0.72)] bg-white/92 p-5 shadow-[0_12px_28px_rgba(33,41,52,0.08)] transition duration-300 hover:-translate-y-1 hover:shadow-[0_18px_34px_rgba(33,41,52,0.12)]">
                          <div
                            className="absolute inset-x-5 top-0 h-1 rounded-full"
                            style={{
                              background: `linear-gradient(90deg, ${item.accentColor} 0%, rgba(255,255,255,0) 100%)`,
                            }}
                          />
                          <div
                            className="absolute -right-6 bottom-4 size-20 rounded-full opacity-[0.1]"
                            style={{ backgroundColor: item.accentColor }}
                          />

                          <div className="relative flex items-start justify-between gap-3">
                            <span
                              className="inline-flex size-14 items-center justify-center rounded-2xl shadow-sm"
                              style={{
                                backgroundColor: `${item.accentColor}16`,
                                color: item.accentColor,
                              }}
                            >
                              <Icon className="size-7" />
                            </span>
                            <ArrowUpRight className="size-5 text-[var(--color-muted)] transition group-hover:text-[var(--color-primary)]" />
                          </div>

                          <div className="relative mt-auto">
                            <h3 className="m-0 font-[family-name:var(--font-heading)] text-2xl font-semibold leading-snug tracking-tight text-[var(--color-text)]">
                              {item.label}
                            </h3>
                            <div className="mt-4 flex items-end justify-between gap-4">
                              <div>
                                <strong className="block font-[family-name:var(--font-heading)] text-4xl font-semibold leading-none text-[var(--color-text)]">
                                  {formatCompactNumber(item.datasetCount)}
                                </strong>
                                <p className="mb-0 mt-2 text-sm font-medium text-[var(--color-muted)]">
                                  Dataset tersedia
                                </p>
                              </div>
                              <span className="text-xs font-semibold uppercase tracking-[0.16em] text-[var(--color-muted)]">
                                Buka topik
                              </span>
                            </div>
                          </div>
                        </article>
                      </Link>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="mt-5 flex items-center justify-center gap-2 sm:hidden">
          {slides.map((slide, index) => (
            <button
              key={`mobile-${slide.id}`}
              type="button"
              onClick={() => goToSlide(index)}
              aria-label={`Tampilkan ${slide.label}`}
              aria-pressed={activeIndex === index}
              className={`h-2.5 rounded-full transition-all ${
                activeIndex === index ? "w-10 bg-[var(--color-primary)]" : "w-2.5 bg-[#c6cfdb]"
              }`}
            />
          ))}
        </div>
      </Card>
    </section>
  );
}
